      resp.body = "{\"error\":\"not_confirmed\",\"detail\":\"confirm must be true\"}";
      return resp;
    }
    auto request = std::make_shared<amr_dispatcher_interfaces::srv::BlockEdge::Request>();
    request->from_station = from_station;
